    class Meta:
        get_latest_by = "created"
        ordering = ("id",)
        verbose_name = _("Ticket")
        verbose_name_plural = _("Tickets")

    def __str__(self) -> str:
        return f"{self.id} {self.title}"

    def get_absolute_url(self) -> str:
        return reverse_lazy("helpdesk:view", args=(self.id,))

    def save(self, *args, **kwargs) -> None:
        if len(self.title) > 200:
            self.title = self.title[:197] + "..."

        super().save(*args, **kwargs)

    @property
    def time_spent(self):
        """Return back total time spent on the ticket. This is calculated value
        based on total sum from all FollowUps
        """
        res = FollowUp.objects.filter(ticket=self).aggregate(models.Sum("time_spent"))
        return res.get("time_spent__sum", datetime.timedelta(0))

    @property
    def time_spent_formated(self):
        return format_time_spent(self.time_spent)

    def send(self, roles, dont_send_to=None, sent_to=None, **kwargs):
        """
        Send notifications to everyone interested in this ticket.

        The roles argument is a dictionary mapping from roles to (template, context) pairs.
        If a role is not present in the dictionary, users of that type will not receive the notification.

        The following roles exist:

          - 'submitter'
          - 'new_ticket_cc'
          - 'ticket_cc'
          - 'assigned_to'

        Here is an example roles dictionary:

        {
            'submitter': (template_name, context),
            'assigned_to': (template_name2, context),
        }

        **kwargs are passed to send_templated_mail defined in templated_email.py

        returns the group of email addresses that won't be mailed to again, which is
        the addresses delivered to and dont_send_to and the queue address.

        """
        recipients = set()

        if dont_send_to is not None:
            recipients.update(dont_send_to)

        recipients.add(self.queue.email_address)

        def send(role, recipient):
            if recipient and recipient not in recipients and role in roles:
                template, context = roles[role]
                delivered = send_templated_mail(
                    template,
                    context,
                    recipient,
                    sender=self.queue.from_address,
                    **kwargs,
                )
                recipients.add(recipient)
                if sent_to is not None and delivered:
                    sent_to.add(recipient)

        send("submitter", self.submitter_email)
        send("ticket_cc", self.queue.updated_ticket_cc)
        send("new_ticket_cc", self.queue.new_ticket_cc)
        if self.assigned_to:
            send("assigned_to", self.assigned_to.email)
        if self.queue.enable_notifications_on_email_events:
            for cc in self.ticketcc_set.all():
                send("ticket_cc", cc.email_address)
        return recipients

    def get_notification_recipients(self, user=None):
        """
        Used to create the informational list of recipients before you send a public
        follow up
        """
        recipients = set()
        exclude = {self.queue.email_address}
        if user and user.email:
            exclude.add(user.email)

        if self.submitter_email and self.submitter_email not in exclude:
            recipients.add(self.submitter_email)

        if (
            self.assigned_to
            and self.assigned_to.email
            and self.assigned_to.email not in exclude
            and self.assigned_to.usersettings_helpdesk.email_on_ticket_change
        ):
            recipients.add(self.assigned_to.email)

        if self.queue.updated_ticket_cc and self.queue.updated_ticket_cc not in exclude:
            recipients.add(self.queue.updated_ticket_cc)

        if self.queue.enable_notifications_on_email_events:
            for cc in self.ticketcc_set.all():
                addr = cc.email_address
                if addr and addr not in exclude:
                    recipients.add(addr)

        return sorted(recipients)

    @property
    def get_assigned_to(self) -> str:
        """Show the full name or username of the staff working on this ticket
        else just say 'Unassigned'."""

        taker = self.assigned_to

        if not taker:
            return _("Unassigned")

        return taker.get_full_name() or taker.get_username()

    @property
    def ticket(self) -> str:
        """A user-friendly ticket ID, which is a combination of ticket ID
        and queue slug. This is generally used in e-mail subjects."""

        return f"[{self.ticket_for_url}]"

    @property
    def ticket_for_url(self) -> str:
        """A URL-friendly ticket ID, used in links."""
        return f"{self.queue.slug}-{self.id}"

    @property
    def get_priority_css_class(self) -> str:
        """
        Return the bootstrap class corresponding to the priority.

        Kept for backwards compatibility: feeds the row_class API field and
        several non-DataTables templates. Note these are bare badge classes
        (e.g. "success") which are inert on <tr> elements in Bootstrap 5;
        see get_priority_badge_class for the badge rendering.
        """
        CSS_MAP = {1: "danger", 2: "warning", 5: "success"}
        return CSS_MAP.get(self.priority, "")

    @property
    def get_status_badge_class(self) -> str:
        """Return the bootstrap class for the status badge, from the setting."""

        return self.STATUS_CSS_CLASSES.get(self.status, "")

    @property
    def get_priority_badge_class(self) -> str:
        """Return the bootstrap class for the priority badge, from the setting."""
        return self.PRIORITY_CSS_CLASSES.get(self.priority, "")

    @property
    def get_status(self) -> str:
        """Displays the ticket status, with an "On Hold" message if needed."""

        held_msg, dep_msg = _("On Hold"), _("Open dependencies")
        status = self.get_status_display()

        if self.on_hold:
            status = f"{status} - {held_msg}"

        if not self.can_be_resolved:
            status = f"{status} - {dep_msg}"

        return status

    def _get_allowed_status_flow(self):
        """
        Returns the list of allowed ticket status modifications for current state.
        """
        status_id_list = self.STATUS_CHOICES_FLOW.get(self.status, ())
        if status_id_list:
            # keep defined statuses in order and add labels for display
            status_dict = dict(helpdesk_settings.TICKET_STATUS_CHOICES)
            new_statuses = [
                (status_id, status_dict.get(status_id, _("No label")))
                for status_id in status_id_list
            ]
        else:
            # defaults to all choices if status was not mapped
            new_statuses = helpdesk_settings.TICKET_STATUS_CHOICES
        return new_statuses

    get_allowed_status_flow = property(_get_allowed_status_flow)

    @property
    def ticket_url(self) -> str:
        """
        Returns a publicly-viewable URL for this ticket, used when giving
        a URL to the submitter of a ticket.
        """
        base_url = build_base_url()
        path = reverse_lazy("helpdesk:public_view")

        return f"{base_url}{path}?ticket={self.ticket_for_url}&email={self.submitter_email}&key={self.secret_key}"

    @property
    def staff_url(self) -> str:
        """The absolute url of a ticket with a fully qualified domain."""

        base_url = build_base_url()
        path = self.get_absolute_url()

        return f"{base_url}{path}"

    @property
    def can_be_resolved(self) -> bool:
        """If all dependencies (if any) on a ticket are resolved then True otherwise False."""

        qs = TicketDependency.objects.filter(ticket=self)
        unresolved_deps = qs.filter(depends_on__status__in=Ticket.OPEN_STATUSES)
        return not unresolved_deps.exists()

    def get_submitter_userprofile(self) -> User | None:
        return User.objects.filter(email=self.submitter_email).first()

    @staticmethod
    def queue_and_id_from_query(query) -> tuple[str, str]:
        """
        Apply the opposite logic here compared to `ticket_for_url`
        Ensure that queues with '-' in them will work

        Ex:
            "pay-1" -> ("pay", "1")
            "1-ord-99-72 -> ("1-ord-99", "72")
        """

        *parts, ticket_id = query.split("-")
        return "-".join(parts), ticket_id

    def get_markdown(self) -> SafeString:
        return get_markdown(self.description)

    @property
    def get_resolution_markdown(self) -> SafeString:
        return get_markdown(self.resolution)

    def add_email_to_ticketcc_if_not_in(
        self,
        email: str | None = None,
        user: User | None = None,
        ticketcc: TicketCC | None = None,
    ) -> TicketCC | None:
        """
        Check that given email/user_email/ticketcc_email is not already present on the ticket
        (submitter email, assigned to, or in ticket CCs) and add it to a new ticket CC,
        or move the given one.
        """

        new_email = (
            getattr(ticketcc, "display", None) or getattr(user, "email", None) or email
        )
        if not new_email:
            raise ValueError(
                "You must provide at least one parameter to get the email from",
            )

        # Prepare all emails already into the ticket
        ticket_emails = [x.display for x in self.ticketcc_set.all()] + [
            self.submitter_email,
            getattr(self.assigned_to, "email", None),
        ]

        # Check that email is not already part of the ticket
        if new_email in ticket_emails:
            return

        if ticketcc:
            ticketcc.ticket = self
            ticketcc.save(update_fields=["ticket"])
        elif user:
            ticketcc, _ = self.ticketcc_set.get_or_create(user=user)
        else:
            ticketcc, _ = self.ticketcc_set.get_or_create(email=new_email)

        return ticketcc

    def public_custom_field_values(self):
        """Custom field values that may be shown to the submitter."""
        return self.ticketcustomfieldvalue_set.filter(
            field__staff_only=False
        ).select_related("field")

    def set_custom_field_values(self) -> None:
        for field in CustomField.objects.all():
            try:
                value = self.ticketcustomfieldvalue_set.get(field=field).value
            except TicketCustomFieldValue.DoesNotExist:
                value = None
            setattr(self, f"custom_{field.name}", value)

    def save_custom_field_values(self, data) -> None:
        for field, value in data.items():
            if field.startswith("custom_"):
                field_name = field.replace("custom_", "", 1)
                customfield = CustomField.objects.get(name=field_name)
                cfv, created = self.ticketcustomfieldvalue_set.get_or_create(
                    field=customfield, defaults={"value": convert_value(value)}
                )
                if not created:
                    cfv.value = convert_value(value)
                    cfv.save()

